-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_DOMICILIOS_HIST_ALTA` AFTER INSERT ON `FB_DOMICILIOS` FOR EACH ROW
BEGIN
IF NEW.VERSION<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_VERSION_INICIAL'; END IF;
IF EXISTS (SELECT 1 FROM FB_CIU_CONSULTAS_WEB WHERE ID_PERSONA=NEW.ID_PERSONA AND ID_CONSULTA>NEW.ID_CONSULTA) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_ORIGEN_ANTIGUO'; END IF;
INSERT INTO FB_DOMICILIOS_HISTORIAL (ID_DOMICILIO,ID_CONSULTA,VERSION,USUARIO_MODIFICADOR_ID,DATOS_ANTERIORES,DATOS_NUEVOS) VALUES (NEW.ID_DOMICILIO,NEW.ID_CONSULTA,NEW.VERSION,NEW.USUARIO_MODIFICADOR_ID,NULL,JSON_OBJECT('id_domicilio',CAST(NEW.`ID_DOMICILIO` AS CHAR),'id_persona',CAST(NEW.`ID_PERSONA` AS CHAR),'id_persona_cp',CAST(NEW.`ID_PERSONA_CP` AS CHAR),'id_domicilio_cp',CAST(NEW.`ID_DOMICILIO_CP` AS CHAR),'id_consulta',CAST(NEW.`ID_CONSULTA` AS CHAR),'calle',NEW.`CALLE`,'numero',NEW.`NUMERO`,'barrio',NEW.`BARRIO`,'localidad',NEW.`LOCALIDAD`,'departamento',NEW.`DEPARTAMENTO`,'codigo_postal',NEW.`CODIGO_POSTAL`,'ph',NEW.`PH`,'block',NEW.`BLOCK`,'depto',NEW.`DEPTO`,'puerta',NEW.`PUERTA`,'domicilio_completo',NEW.`DOMICILIO_COMPLETO`,'referencia',NEW.`REFERENCIA`,'sector',NEW.`SECTOR`,'manzana',NEW.`MANZANA`,'lote',NEW.`LOTE`,'version',NEW.`VERSION`,'fecha_alta',NEW.`FECHA_ALTA`,'fecha_modificacion',NEW.`FECHA_MODIFICACION`,'usuario_modificador_id',NEW.`USUARIO_MODIFICADOR_ID`,'verificacion_cp_json',JSON_QUERY(NEW.`VERIFICACION_CP_JSON`,'$')));
END$$
DELIMITER ;
